import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('lifecycle and status derivation', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('a', 3)).ok, false);
  assert.equal((await h.taskStarted('a', 1.5)).ok, false);
  assert.equal((await h.taskCompleted('a', 0)).ok, false);
  await h.taskStarted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskEvicted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  await h.taskRequeued('a', 0);
  for (const t of [0, 1, 2]) await h.taskStarted('a', t);
  for (const t of [0, 1, 2]) await h.taskEvicted('a', t);
  assert.equal((await h.run('a'))!.status, 'evicted');
  await h.taskRequeued('a', 0);
  await h.taskStarted('a', 0);
  await h.taskCompleted('a', 0);
  assert.equal((await h.run('a'))!.status, 'running');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.run('a'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.start('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('failed and completed', async () => {
  const h = await createHost();
  await h.start('b');
  await h.taskStarted('b', 0);
  await h.taskFailed('b', 0);
  assert.equal((await h.run('b'))!.status, 'failed');
  assert.equal((await h.taskStarted('b', 1)).ok, false);
  await h.start('c');
  for (const t of [0, 1, 2]) { await h.taskStarted('c', t); await h.taskCompleted('c', t); }
  assert.equal((await h.run('c'))!.status, 'completed');
});

